    "pfe64a32f": {"title": "Feodosia", "painter": "Konstantin Bogaevsky", "born": 1872, "died": 1943, "about": "Konstantin Fyodorovich Bogaevsky was a Ukrainian and Russian painter from Crimea, notable for his Symbolist landscapes.", "about_of": "painter", "wiki_url": "https://en.wikipedia.org/wiki/Konstantin_Bogaevsky"},
    "pfeee79d4": {"title": "Ballerinas Adjusting Their Dresses", "painter": "Edgar Degas", "born": 1834, "died": 1917, "movement": "Impressionism", "about": "Edgar Degas was a French Impressionist artist famous for his pastel drawings and oil paintings. Degas also produced wax sculptures, prints, and drawings. Degas is especially identified with the subject of dance; more than half of his works depict dancers.", "about_of": "painter", "wiki_url": "https://en.wikipedia.org/wiki/Edgar_Degas"},
